function section(id,title,copy){const s=make('section','','seller-section final-workspace');s.id='section-'+id;s.append(make('h1',title),make('p',copy));document.querySelector('.seller-workspace').append(s);return s;}
function metric(root,label,value,tab){const b=btn('',()=>window.showTab(tab));b.className='final-metric';b.append(make('span',label),make('strong',String(value??'—')));root.append(b);}
const statusTones={approved:'good',published:'good',accepted:'good',delivered:'good',paid:'good',completed:'good',closed:'good',replaced:'good',refunded:'good',active:'good',rejected:'bad',changes_requested:'bad',failed:'bad',cancelled:'bad',void:'bad',error:'bad',blocked:'bad',pending:'waiting',under_review:'waiting',requested:'waiting',reserved:'waiting',creating:'waiting',booking_unknown:'waiting',needs_attention:'waiting',new:'waiting',packed:'info',shipped:'info',out_for_delivery:'info',in_progress:'info',draft:'neutral'};
