const catalogIntro=document.querySelector('#section-add-product .ccat-intro');if(catalogIntro){const actions=catalogIntro.querySelector('.ccat-actions'),single=$('hubSingleCatalog');if(actions&&single)actions.append(single);const stats=catalogIntro.querySelector('.ccat-overview');if(stats&&!catalogIntro.querySelector('.seller-catalog-overview-title'))stats.before(make('h3','Overview','seller-catalog-overview-title'));const banner=make('div','','seller-catalog-quality-banner'),art=make('span','','seller-catalog-quality-art');art.setAttribute('aria-hidden','true');art.innerHTML='<svg viewBox="0 0 64 64" fill="none"><rect x="16" y="8" width="34" height="46" rx="5" fill="#fff" stroke="#b38b50" stroke-width="2"/><path d="M24 22h18M24 30h18M24 38h10" stroke="#c9a770" stroke-width="3" stroke-linecap="round"/><circle cx="48" cy="46" r="13" fill="#f1debd"/><path d="m42 46 4 4 7-8" stroke="#99712e" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"/></svg>';const copy=make('div');copy.append(make('strong','Make your catalog ready for customers'),make('p','Check product details, images and approval feedback before your next upload.'));const action=btn('Review listing quality',()=>window.showTab('listing-checks'));action.classList.remove('seller-btn-outline');banner.append(art,copy,action);catalogIntro.before(banner);}
const savedNoticeBadge=document.querySelector('.studio-nav-count');if(savedNoticeBadge)savedNoticeBadge.hidden=!savedNoticeBadge.textContent.trim();if(savedNoticeBadge)document.querySelector('.hub-menu-scroll [data-tab="notices"]')?.append(savedNoticeBadge);
