const command=$('sellerCommandInput'),results=$('sellerCommandResults');command?.addEventListener('input',()=>{const term=command.value.trim().toLowerCase();if(!term){results.replaceChildren();results.hidden=true;command.setAttribute('aria-expanded','false');return;}results.replaceChildren();for(const [tab,label] of navItems.filter(x=>(x[0]+' '+x[1]+' '+(pageCopy[x[0]]||'')).toLowerCase().includes(term)))results.append(btn(label,()=>{results.hidden=true;command.setAttribute('aria-expanded','false');command.value='';window.showTab(tab);}));if(!results.children.length)results.append(make('p','No tool found. Try order, stock, discount or support.'));results.hidden=false;command.setAttribute('aria-expanded','true');});
document.addEventListener('visibilitychange',()=>{if(!document.hidden&&$('section-overview')?.classList.contains('active')&&window.CeroodSellerAuth?.getToken?.())loadSummary();});
const legacyBadges='.approval-badge,.studio-status,.seller-order-status,.ci-badge,.ccat-chip,.cr-live-badge,.return-status';
function colourLegacyBadges(root){const nodes=[];if(root.matches?.(legacyBadges))nodes.push(root);root.querySelectorAll?.(legacyBadges).forEach(n=>nodes.push(n));for(const n of nodes){const raw=String(n.dataset.status||n.textContent||'').trim().toLowerCase().replaceAll(' ','_');const key=[...n.classList].find(c=>statusTones[c])||({'under_review':'pending','needs_changes':'rejected','processing':'in_progress','confirmed':'accepted','not_shipped':'pending','awaiting_payment':'pending'}[raw])||raw;const tone=statusTones[key]||'neutral';if(n.dataset.sellerTone!==tone)n.dataset.sellerTone=tone;}}
colourLegacyBadges($('dashboardContent'));const statusObserver=new MutationObserver(records=>{for(const r of records){if(r.type==='characterData')colourLegacyBadges(r.target.parentElement);else if(r.type==='attributes')colourLegacyBadges(r.target);else for(const n of r.addedNodes)if(n.nodeType===1)colourLegacyBadges(n);}});statusObserver.observe($('dashboardContent'),{subtree:true,childList:true,characterData:true,attributes:true,attributeFilter:['class']});
